namespace sv_72baedad9a70449d801c0c6cc7b3d0ef.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public sealed class ThemeState
{
    public ThemeMode Mode { get; set; } = ThemeMode.System;
    public string AccentColor { get; set; } = "#0d6efd";
}

/// <summary>
/// Scoped service that keeps the current theme in sync with the browser
/// via JS interop. Interactive components subscribe to OnChange; the JS
/// module handles localStorage persistence and CSS attribute application
/// so that even static-SSR parts of the layout reflect the theme.
/// </summary>
public sealed class ThemeService : IAsyncDisposable
{
    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;
    private readonly ThemeState _state = new();

    public event Action? OnChange;

    public ThemeMode Mode => _state.Mode;
    public string AccentColor => _state.AccentColor;

    public ThemeService(IJSRuntime js)
    {
        _js = js;
    }

    /// <summary>
    /// Called once by the first interactive component that renders.
    /// Loads the JS module and reads persisted values from localStorage.
    /// </summary>
    public async Task InitializeAsync()
    {
        if (_module is not null) return;

        _module = await _js.InvokeAsync<IJSObjectReference>(
            "import", "./_content/sv-72baedad9a70449d801c0c6cc7b3d0ef/js/theme.js");

        var stored = await _module.InvokeAsync<ThemeDto?>("getTheme");
        if (stored is not null)
        {
            _state.Mode = Enum.TryParse<ThemeMode>(stored.Mode, true, out var m) ? m : ThemeMode.System;
            _state.AccentColor = stored.AccentColor ?? _state.AccentColor;
        }
    }

    public async Task SetModeAsync(ThemeMode mode)
    {
        _state.Mode = mode;
        await ApplyAsync();
        OnChange?.Invoke();
    }

    public async Task SetAccentColorAsync(string color)
    {
        _state.AccentColor = color;
        await ApplyAsync();
        OnChange?.Invoke();
    }

    public async Task SetThemeAsync(ThemeMode mode, string accentColor)
    {
        _state.Mode = mode;
        _state.AccentColor = accentColor;
        await ApplyAsync();
        OnChange?.Invoke();
    }

    private async Task ApplyAsync()
    {
        if (_module is null) return;
        await _module.InvokeVoidAsync("setTheme", _state.Mode.ToString(), _state.AccentColor);
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }

    // DTO for JS interop deserialization
    public sealed class ThemeDto
    {
        public string? Mode { get; set; }
        public string? AccentColor { get; set; }
    }
}

const STORAGE_KEY = "app-theme";

function applyToDocument(mode, accentColor) {
    const root = document.documentElement;

    // Resolve "System" to the OS preference
    let resolved = mode;
    if (mode === "System") {
        resolved = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "Dark" : "Light";
    }

    root.setAttribute("data-bs-theme", resolved.toLowerCase());
    root.setAttribute("data-theme-mode", mode);
    root.style.setProperty("--app-accent-color", accentColor);
}

/** Read persisted theme from localStorage. Returns null if nothing stored. */
export function getTheme() {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return null; }
}

/** Persist and apply theme. Called from C# ThemeService. */
export function setTheme(mode, accentColor) {
    const data = { Mode: mode, AccentColor: accentColor };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    applyToDocument(mode, accentColor);
}

// On page load (including enhanced navigations), apply the stored theme
// immediately so there's no flash of unstyled content.
(function autoApply() {
    const theme = getTheme();
    if (theme) {
        applyToDocument(theme.Mode ?? "System", theme.AccentColor ?? "#0d6efd");
    }
})();

// Re-apply when OS preference changes (relevant for "System" mode)
window.matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", () => {
        const theme = getTheme();
        if (theme && theme.Mode === "System") {
            applyToDocument("System", theme.AccentColor ?? "#0d6efd");
        }
    });

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<span class="theme-indicator" title="Current theme">
    @ThemeIcon @Theme.Mode
    <span class="accent-dot" style="background-color: @Theme.AccentColor;"></span>
</span>

@code {
    private string ThemeIcon => Theme.Mode switch
    {
        ThemeMode.Dark => "🌙",
        ThemeMode.Light => "☀️",
        _ => "💻"
    };

    protected override async Task OnInitializedAsync()
    {
        await Theme.InitializeAsync();
        Theme.OnChange += HandleThemeChange;
    }

    private void HandleThemeChange()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChange;
    }
}

.theme-indicator {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.85rem;
    padding: 0.25rem 0.6rem;
    border-radius: 0.5rem;
    background: var(--bs-tertiary-bg, #e9ecef);
}

.accent-dot {
    display: inline-block;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 1px solid rgba(0, 0, 0, 0.15);
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <div class="btn-group d-flex" role="group">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    var isActive = mode == selectedMode;
                    <button type="button"
                            class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => SelectMode(mode)">
                        @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="accent-color">Accent Color</label>
            <div class="d-flex align-items-center gap-3">
                <input type="color" id="accent-color" class="form-control form-control-color"
                       value="@selectedAccent"
                       @onchange="AccentChanged" />
                <code>@selectedAccent</code>
            </div>
        </div>

        <button class="btn btn-success" @onclick="SaveAsync">
            Save Preferences
        </button>

        @if (saved)
        {
            <span class="text-success ms-3">✓ Saved</span>
        }
    </div>
</div>

@code {
    private ThemeMode selectedMode;
    private string selectedAccent = "#0d6efd";
    private bool saved;

    protected override async Task OnInitializedAsync()
    {
        await Theme.InitializeAsync();
        selectedMode = Theme.Mode;
        selectedAccent = Theme.AccentColor;
        Theme.OnChange += HandleThemeChange;
    }

    private void SelectMode(ThemeMode mode) => selectedMode = mode;

    private void AccentChanged(ChangeEventArgs e)
    {
        selectedAccent = e.Value?.ToString() ?? selectedAccent;
    }

    private async Task SaveAsync()
    {
        await Theme.SetThemeAsync(selectedMode, selectedAccent);
        saved = true;
    }

    private void HandleThemeChange()
    {
        selectedMode = Theme.Mode;
        selectedAccent = Theme.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChange;
    }
}

