const STORAGE_KEY = "app-theme";

function applyToDocument(mode, accentColor) {
    const root = document.documentElement;

    // Resolve "System" to the OS preference
    let resolved = mode;
    if (mode === "System") {
        resolved = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "Dark" : "Light";
    }

    root.setAttribute("data-bs-theme", resolved.toLowerCase());
    root.setAttribute("data-theme-mode", mode);
    root.style.setProperty("--app-accent-color", accentColor);
}

/** Read persisted theme from localStorage. Returns null if nothing stored. */
export function getTheme() {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    try { return JSON.parse(raw); } catch { return null; }
}

/** Persist and apply theme. Called from C# ThemeService. */
export function setTheme(mode, accentColor) {
    const data = { Mode: mode, AccentColor: accentColor };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    applyToDocument(mode, accentColor);
}

// On page load (including enhanced navigations), apply the stored theme
// immediately so there's no flash of unstyled content.
(function autoApply() {
    const theme = getTheme();
    if (theme) {
        applyToDocument(theme.Mode ?? "System", theme.AccentColor ?? "#0d6efd");
    }
})();

// Re-apply when OS preference changes (relevant for "System" mode)
window.matchMedia("(prefers-color-scheme: dark)")
    .addEventListener("change", () => {
        const theme = getTheme();
        if (theme && theme.Mode === "System") {
            applyToDocument("System", theme.AccentColor ?? "#0d6efd");
        }
    });

