toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService Theme

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <div class="btn-group d-flex" role="group">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    var isActive = mode == selectedMode;
                    <button type="button"
                            class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                            @onclick="() => SelectMode(mode)">
                        @mode
                    </button>
                }
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label" for="accent-color">Accent Color</label>
            <div class="d-flex align-items-center gap-3">
                <input type="color" id="accent-color" class="form-control form-control-color"
                       value="@selectedAccent"
                       @onchange="AccentChanged" />
                <code>@selectedAccent</code>
            </div>
        </div>

        <button class="btn btn-success" @onclick="SaveAsync">
            Save Preferences
        </button>

        @if (saved)
        {
            <span class="text-success ms-3">✓ Saved</span>
        }
    </div>
</div>

@code {
    private ThemeMode selectedMode;
    private string selectedAccent = "#0d6efd";
    private bool saved;

    protected override async Task OnInitializedAsync()
    {
        await Theme.InitializeAsync();
        selectedMode = Theme.Mode;
        selectedAccent = Theme.AccentColor;
        Theme.OnChange += HandleThemeChange;
    }

    private void SelectMode(ThemeMode mode) => selectedMode = mode;

    private void AccentChanged(ChangeEventArgs e)
    {
        selectedAccent = e.Value?.ToString() ?? selectedAccent;
    }

    private async Task SaveAsync()
    {
        await Theme.SetThemeAsync(selectedMode, selectedAccent);
        saved = true;
    }

    private void HandleThemeChange()
    {
        selectedMode = Theme.Mode;
        selectedAccent = Theme.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChange;
    }
}

